{"content":"package pipeline;

import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVParser;
import org.apache.commons.csv.CSVRecord;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Nightly supplier feed importer.
 *
 * <p>Reads supplier CSVs and produces a per-SKU summary. Rows are parsed with Apache Commons CSV
 * (quoted fields, embedded commas and quotes are handled correctly). Processing is parallel and
 * deterministic: each worker accumulates into its own local map, and the maps are merged after
 * join, so repeated runs over the same file always produce identical totals and per-SKU results.
 */
public final class Importer {

    public static final boolean WORKERS_ENABLED = true;   // safe now: per-thread locals, merged on join
    public static final int NUM_WORKERS = 4;

    /** What one import produced. Other tooling reads these three fields by name. */
    public static final class Summary {
        public final int skus;
        public final int rows;
        public final Map<String, Double> totals;

        public Summary(int skus, int rows, Map<String, Double> totals) {
            this.skus = skus;
            this.rows = rows;
            this.totals = totals;
        }
    }

    /** Number of data rows skipped for each malformed-input reason. */
    public static final class Skips {
        public final long blankQuantity;
        public final long unparseableQuantity;
        public final long unparseablePrice;
        public final long missingColumns;

        public Skips() {
            blankQuantity = 0;
            unparseableQuantity = 0;
            unparseablePrice = 0;
            missingColumns = 0;
        }
    }

    /** Per-worker accumulator: local to each thread so no shared state is mutated concurrently. */
    static final class Local {
        final Map<String, Double> totals = new HashMap<>();
        long rows = 0;
        final Skips skips = new Skips();
    }

    static void worker(Local local, List<Map<String, String>> rows) {
        for (Map<String, String> row : rows) {
            try {
                processRow(local, row);
            } catch (MissingColumnException e) {
                local.skips.missingColumns++;
            } catch (QuantityException e) {
                local.skips.unparseableQuantity++;
            } catch (PriceException e) {
                local.skips.unparseablePrice++;
            }
        }
    }

    static void processRow(Local local, Map<String, String> row) {
        String sku = row.get("sku");
        if (sku == null) {
            throw new MissingColumnException();
        }
        String quantity = row.get("quantity");
        if (quantity == null || quantity.isBlank()) {
            throw new QuantityException("blank");
        }
        String price = row.get("unit_price");
        if (price == null) {
            throw new MissingColumnException();
        }
        double value;
        try {
            value = Double.parseDouble(quantity.strip()) * parsePrice(price);
        } catch (NumberFormatException e) {
            throw new QuantityException(e.getMessage());
        } catch (PriceException e) {
            throw e;
        }
        local.totals.merge(sku, value, Double::sum);
        local.rows++;
    }

    /** Parse a unit price, stripping currency symbols and surrounding whitespace. */
    static double parsePrice(String price) {
        String cleaned = price.strip();
        try {
            // Remove a leading currency symbol such as "$".
            String digits = cleaned.replaceFirst("^[$€£]", "");
            return Double.parseDouble(digits);
        } catch (NumberFormatException e) {
            throw new PriceException(e.getMessage());
        }
    }

    /** A required column (sku or unit_price) is absent on this row. */
    static final class MissingColumnException extends RuntimeException {
    }

    /** The quantity field is blank or not a number. */
    static final class QuantityException extends RuntimeException {
        QuantityException(String message) {
            super(message);
        }
    }

    /** The price field is not a number after cleaning. */
    static final class PriceException extends RuntimeException {
        PriceException(String message) {
            super(message);
        }
    }

    /** Every SKU seen, as a set (O(n) instead of the old O(n^2) linear scan). */
    public static List<String> knownSkus(List<Map<String, String>> rows) {
        Map<String, Boolean> seen = new HashMap<>();
        for (Map<String, String> r : rows) {
            seen.putIfAbsent(r.get("sku"), Boolean.TRUE);
        }
        return new ArrayList<>(seen.keySet());
    }

    public static List<Map<String, String>> load(String path) throws IOException {
        try (BufferedReader br = Files.newBufferedReader(Path.of(path))) {
            CSVParser parser = new CSVParser(br, CSVFormat.DEFAULT.builder()
                    .setHeader()
                    .setIgnoreSurroundingSpaces(true)
                    .build());
            List<Map<String, String>> out = new ArrayList<>();
            for (CSVRecord record : parser) {
                Map<String, String> row = new HashMap<>();
                for (String name : record.getHeaderMap().keySet()) {
                    row.put(name, record.get(name));
                }
                out.add(row);
            }
            return out;
        }
    }

    /** Import one feed file and return the per-SKU totals and the number of rows imported. */
    public static Summary summarize(String path) throws Exception {
        List<Map<String, String>> rows = load(path);

        List<String> skus = knownSkus(rows);

        Local[] locals = new Local[NUM_WORKERS];
        for (int i = 0; i < locals.length; i++) {
            locals[i] = new Local();
        }

        int chunk = Math.max(1, rows.size() / NUM_WORKERS);
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < rows.size(); i += chunk) {
            List<Map<String, String>> slice = rows.subList(i, Math.min(i + chunk, rows.size()));
            int localIndex = (int) (i / (long) chunk);
            threads.add(new Thread(() -> worker(locals[localIndex], slice)));
        }
        for (Thread t : threads) {
            t.start();
        }
        for (Thread t : threads) {
            t.join();
        }

        Local master = locals[0];
        for (int i = 1; i < locals.length; i++) {
            merge(locals[i], master);
        }

        Map<String, Double> totals = new TreeMap<>();
        totals.putAll(master.totals);

        return new Summary(master.totals.size(), (int) master.rows, totals);
    }

    static void merge(Local source, Local target) {
        target.totals.putAll(source.totals);
        target.rows += source.rows;
        target.skips.blankQuantity += source.skips.blankQuantity;
        target.skips.unparseableQuantity += source.skips.unparseableQuantity;
        target.skips.unparseablePrice += source.skips.unparseablePrice;
        target.skips.missingColumns += source.skips.missingColumns;
    }

    public static void main(String[] args) throws Exception {
        String path = args.length > 0 ? args[0] : Path.of("data", "feed.csv").toString();
        Summary result = summarize(path);
        System.out.printf("imported %d rows covering %d SKUs%n", result.rows, result.skus);
        List<String> keys = new ArrayList<>(result.totals.keySet());
        for (String sku : keys) {
            System.out.printf("  %s: %.2f%n", sku, result.totals.get(sku));
        }
        System.out.printf("skipped: blankQuantity=%d unparseableQuantity=%d unparseablePrice=%d missingColumns=%d%n",
                result.skips, result.skips, result.skips, result.skips);
    }
}
